            default: next_state_b_fsm = S_IDLE;
        endcase
    end

    // Output Assignments based on FSM State
    assign a_isolate_o = (state_b_fsm == S_ISOLATE_A) ? 1'b0 : 1'b1;
    assign b_isolate_o = (state_b_fsm == S_ISOLATE_B) ? 1'b0 : 1'b1;
    assign a_clear_o = (state_b_fsm == S_CLEAR_A) ? 1'b0 : 1'b1;
    assign b_clear_o = (state_b_fsm == S_CLEAR_B) ? 1'b0 : 1'b1;

    // ------------------------------------------------------------------
    // Input Capture Logic (Domain A)
    // ------------------------------------------------------------------
    // Note: The module interface has 'a_clear_i' as input.
    // We need to capture this in Domain B.
