    // reg a_isolate_ack; assign a_isolate_ack = a_isolate_ack_i;

    // Let's correct the input capture logic.

    // Corrected Input Capture for Domain A -> Domain B
    assign a_clear_req = a_clear_i;
    assign a_clear_ack = a_clear_ack_i;
    assign a_isolate_ack = a_isolate_ack_i;
    // There is no 'a_isolate_req' input. The request is implicit in 'a_clear_i'.
    // The isolation is driven by the controller.

    // Corrected Input Capture for Domain B -> Domain A
    assign b_clear_req = b_clear_i;
    assign b_clear_ack = b_clear_ack_i;
    assign b_isolate_ack = b_isolate_ack_i;
    // There is no 'b_isolate_req' input.

    // Re-verify the sync logic variables.
