    // So 'a_clear_req_sync' is sufficient to trigger the sequence.

    // Let's rewrite the sync blocks to only include necessary signals.

    // Sync A signals to B
    genvar j;
    generate
        for (j = 0; j < SYNC_STAGES; j = j + 1) begin : sync_a_to_b
            always @(posedge b_clk_i or negedge b_rst_ni) begin : not_rst
                if (!b_rst_ni) begin
                    a_clear_req_sync[j] <= 1'b0;
                    a_clear_ack_sync[j] <= 1'b0;
                    a_isolate_ack_sync[j] <= 1'b0;
