    endgenerate

    // Sync B signals to A
    generate
        for (j = 0; j < SYNC_STAGES; j = j + 1) begin : sync_b_to_a
            always @(posedge a_clk_i or negedge a_rst_ni) begin : not_rst
                if (!a_rst_ni) begin
                    b_clear_req_sync[j] <= 1'b0;
                    b_clear_ack_sync[j] <= 1'b0;
                    b_isolate_ack_sync[j] <= 1'b0;
